202	        }
203	    } else {
204	        if (tileDataContinue) [[likely]] {
205	            unsigned totalRepeats = (validRow * validCol + elementsPerRepeat - 1) / elementsPerRepeat;
206	            bool nonVLAligned = ((validCol > elementsPerRepeat) && ((validCol % elementsPerRepeat) != 0));
207	            bool enableCountMode = nonVLAligned || (totalRepeats > pto::REPEAT_MAX);
208	            if (enableCountMode) [[unlikely]] {
209	                BinS1LCountMode<Op, T>(dst, src0, src1, validRow, validCol);
210	            } else {
211	                BinS1LNormMode<Op, T, elementsPerRepeat, blockSizeElem, TileDataDst::Cols>(
212	                    dst, src0, src1, validRow, validCol);
213	            }
214	        } else {
215	            constexpr unsigned normColRepeat = TileDataDst::Cols / elementsPerRepeat;
216	            constexpr bool countMode = (normColRepeat > 1) && ((TileDataDst::Rows * normColRepeat) < SMALL_RPT) &&
217	                                       ((TileDataSrc::Rows * normColRepeat) < SMALL_RPT);
218	            constexpr bool isColRpt =
219	                (TileDataDst::Rows < (normColRepeat + 1)) && (TileDataSrc::Rows < (normColRepeat + 1));
220	            if constexpr (countMode) {
221	                BinS2LCountMode<Op, T, dstStride, srcStride>(dst, src0, src1, validRow, validCol);
222	            } else if constexpr (isColRpt) {
223	                unsigned tailElements = validCol % elementsPerRepeat;
224	                if (tailElements) {
225	                    BinS2LCountMode<Op, T, dstStride, srcStride>(dst, src0, src1, validRow, validCol);
226	                } else {
227	                    BinS2LNormModeColVLAlign<Op, T, elementsPerRepeat, dstStride, srcStride>(
228	                        dst, src0, src1, validRow, validCol);
229	                }
230	            } else {
231	                BinS2LNormModeRowRpt<Op, T, TileDataDst::Rows, elementsPerRepeat, blockSizeElem, dstStride, srcStride>(
232	                    dst, src0, src1, validRow, validCol);
233	            }
234	        }
235	    }
236	}
